package dev.mcc.game;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class GameEventSpecTest {
 @Test void twentyFourDistinctEventsHaveValidTypedDefaults(){assertEquals(24,GameEventSpec.DEFINITIONS.size());assertEquals(24,GameEventSpec.DEFINITIONS.stream().map(GameEventSpec.Definition::id).distinct().count());for(var definition:GameEventSpec.DEFINITIONS){var config=GameEventSpec.normalize(Map.of("preset",definition.id(),"world","fixture"));assertEquals(definition.id(),config.get("preset"));assertTrue(((Number)config.get("count")).intValue()>0);assertThrows(UnsupportedOperationException.class,()->config.put("radius",100));}}
 @Test void lootBoundsAreValidatedBeforeAnyRuntimeEffect(){for(Object rows:List.of(List.of(),List.of(Map.of("material","DIAMOND","amount",65)),List.of(Map.of("material","DIAMOND","weight",0)),List.of(Map.of("material","DIAMOND","amount",1.5)),Collections.nCopies(13,Map.of("material","DIAMOND"))))assertThrows(IllegalArgumentException.class,()->GameEventSpec.normalize(Map.of("preset","treasure","loot",rows)));var value=GameEventSpec.normalize(Map.of("preset","treasure","loot",List.of(Map.of("material","DIAMOND","amount",3,"weight",2),Map.of("material","IRON_INGOT","amount",12,"weight",5))));assertEquals(2,((List<?>)value.get("loot")).size());}
 @Test void weightedBoundaryDoesNotBiasFirstOrLastResource(){var rows=GameEventSpec.loot(List.of(Map.of("material","DIAMOND","weight",2),Map.of("material","IRON_INGOT","weight",3)));assertEquals(List.of(0,0,1,1,1),java.util.stream.IntStream.range(0,5).map(i->GameEventSpec.weightedIndex(rows,i)).boxed().toList());assertEquals(1,GameEventSpec.weightedIndex(rows,-1));}
 @Test void OldAnimalsAndBossAliasesRemainUsableButUnsafeMobsReject(){assertEquals("sanctuary",GameEventSpec.normalize(Map.of("preset","animals")).get("preset"));assertEquals("champion",GameEventSpec.normalize(Map.of("preset","boss")).get("preset"));for(String mob:List.of("WITHER","ENDER_DRAGON","WARDEN","CREEPER","GHAST"))assertThrows(IllegalArgumentException.class,()->GameEventSpec.normalize(Map.of("preset","waves","mob",mob)));}
 @Test void RouteAndCoordinateErrorsRejectAtomically(){assertThrows(IllegalArgumentException.class,()->GameEventSpec.normalize(Map.of("preset","checkpoint-race","checkpoints",List.of(Map.of("x",0,"y",0,"z",0)))));assertThrows(IllegalArgumentException.class,()->GameEventSpec.normalize(Map.of("preset","checkpoint-race","checkpoints",List.of(Map.of("x",0,"y",0,"z",0),Map.of("x",33,"y",0,"z",0)))));assertThrows(IllegalArgumentException.class,()->GameEventSpec.normalize(Map.of("preset","fireworks","x",1)));assertThrows(IllegalArgumentException.class,()->GameEventSpec.normalize(Map.of("preset","fireworks","radius",Double.NaN)));assertThrows(IllegalArgumentException.class,()->GameEventSpec.normalize(Map.of("preset","fireworks","color","#00ff00")));}
}
